import{_ as t,o,c as d,ag as a}from"./chunks/framework.HG0H2VLS.js";const p=JSON.parse('{"title":"Datatables — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/components/Datatables/Datatables.figma-notes.md","filePath":"public/demos/src/components/Datatables/Datatables.figma-notes.md"}'),i={name:"public/demos/src/components/Datatables/Datatables.figma-notes.md"};function r(n,e,s,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="datatables-—-figma-notes" tabindex="-1">Datatables — Figma Notes <a class="header-anchor" href="#datatables-—-figma-notes" aria-label="Permalink to &quot;Datatables — Figma Notes&quot;">​</a></h1><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI Design System)</li><li><strong>Component set / container:</strong> <code>2562:8289</code></li><li><strong>Tier:</strong> <code>Component</code> → built into <code>src/components/Datatables/</code></li><li>URL: <a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2562-8289" target="_blank" rel="noreferrer">https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2562-8289</a></li></ul><h2 id="variant-matrix-11-variants" tabindex="-1">Variant matrix (11 variants) <a class="header-anchor" href="#variant-matrix-11-variants" aria-label="Permalink to &quot;Variant matrix (11 variants)&quot;">​</a></h2><p>Properties: <strong>Type × Device × Overflow Content</strong>.</p><table tabindex="0"><thead><tr><th>Node ID</th><th>Type</th><th>Device</th><th>Overflow Content</th><th>Built</th></tr></thead><tbody><tr><td>2562:8288</td><td>Pagination</td><td>Desktop</td><td>Scroll</td><td>✅ via base <code>.datatables</code></td></tr><tr><td>2562:8284</td><td>Pagination</td><td>Mobile</td><td>Scroll</td><td>✅ via <code>.datatables.datatables--mobile-scroll</code></td></tr><tr><td>2562:8286</td><td>Pagination</td><td>Mobile</td><td>Trigger</td><td>✅ via row markup with <code>.datatables__row</code> + <code>.datatables__row-detail</code> pairs</td></tr><tr><td>2562:8287</td><td>Search</td><td>Desktop</td><td>Scroll</td><td>✅ via base <code>.datatables</code> (toolbar swapped for search input + View/Export buttons)</td></tr><tr><td>2562:8285</td><td>Search</td><td>Mobile</td><td>Scroll</td><td>✅ via <code>.datatables.datatables--mobile-scroll</code></td></tr><tr><td>2562:8283</td><td>Search</td><td>Mobile</td><td>Trigger</td><td>✅ via kebab row markup</td></tr><tr><td>2764:2397</td><td>Whos Online</td><td>Desktop</td><td>Scroll</td><td>✅ via Avatar + Button cells in body rows</td></tr><tr><td>2764:2715</td><td>Whos Online</td><td>Mobile</td><td>Scroll</td><td>✅ via <code>.datatables--mobile-scroll</code> + 2-column row (User, Account)</td></tr><tr><td>2764:2980</td><td>Whos Online</td><td>Mobile</td><td>Trigger</td><td>✅ via 2-column row (User, Login) + kebab expand for Account/Touch</td></tr><tr><td>3648:164786</td><td><strong>Orders</strong></td><td>Desktop</td><td>Scroll</td><td>✅ via <code>.datatables--orders</code>, rendered from config</td></tr><tr><td>3648:164467</td><td><strong>Orders</strong></td><td>Mobile</td><td>Trigger</td><td>✅ via <code>.datatables--orders</code> + container query (ORDER + CUSTOMER only)</td></tr></tbody></table><p>Type × Device are pure layout/style differences. Overflow Content is a markup difference: Scroll uses normal table rows; Trigger uses paired <code>&lt;tr&gt;</code> rows where the second row holds a hidden <code>&lt;dl&gt;</code> revealed when its sibling row&#39;s kebab checkbox is checked.</p><p>The <strong>Orders</strong> type (added 2026-09-17 for the Listing Screen template) is the first Type driven by a <strong>data renderer</strong> rather than hand-authored rows — see <code>src/cc/templates/ListingScreen/</code>. It has no Desktop-Trigger or Mobile-Scroll variant in Figma, so the set is 11, not 12.</p><p>Everything Orders-specific is scoped to <code>.datatables--orders</code>. That is deliberate: the Orders design disagrees with the values the earlier three Types were built from, and the designer&#39;s call (2026-09-17) was to scope rather than migrate so Pagination / Search / Whos Online keep the rendering they were signed off with. The deltas:</p><table tabindex="0"><thead><tr><th>Element</th><th>Types 1–3</th><th>Orders</th></tr></thead><tbody><tr><td>Toolbar background</td><td><code>--ai-datatable-table-header-bg</code></td><td><code>--ai-surface-primary</code> (desktop only; mobile reverts)</td></tr><tr><td>Footer background</td><td><code>--ai-datatable-table-footer-bg</code></td><td><code>--ai-surface-primary</code> (desktop only)</td></tr><tr><td><code>__user-name</code> weight</td><td><code>--ai-font-bold</code></td><td><code>--ai-font-semibold</code></td></tr><tr><td><code>__user-role</code></td><td><code>--ai-font-body</code> / medium / <code>--ai-text-contrast</code></td><td><code>--ai-font-title</code> / regular / <code>--ai-text-secondary</code></td></tr><tr><td>Column header <code>th</code></td><td>semibold / <code>--ai-text-secondary</code> (Table)</td><td><code>--ai-font-bold</code> / <code>--ai-text-contrast</code> (designer, 2026-09-23; was medium / <code>--ai-text-primary</code> from the Orders frame). Mobile still steps the weight to semibold. The <strong>active sort</strong> label stays contrast too (<code>.datatables__sort--active</code> darkens it to primary on the other Types); its chevron keeps <code>--ai-icon-contrast</code> like the others, so the active column is marked by the single direction chevron&#39;s shape alone</td></tr><tr><td><code>__user-cell</code> gap</td><td><code>--ai-spacing-3</code></td><td><code>--ai-spacing-4</code></td></tr><tr><td><code>__page-btn--active</code> bg</td><td><code>--ai-datatable-table-border</code></td><td><code>--ai-datatable-table-footer-bg</code></td></tr><tr><td><code>__select</code> height</td><td><code>--ai-spacing-8</code> (40px)</td><td><s><code>--ai-spacing-7</code> (32px)</s> — back to 40px, the base button height, on the designer&#39;s call 2026-09-23 (the full-width Listings frame <code>3788:16762</code> also draws it at 40). No Orders override now</td></tr></tbody></table><p>Only the toolbar background difference is invisible in CC light — the two tokens both resolve to <code>#ffffff</code> there and diverge only in CC dark.</p><p>The <strong>Whos Online</strong> type combines the page-size selector AND the search input in a single toolbar (no action buttons). Body rows compose Avatar + Portraits in the USER cell and a tertiary Button in the ACCOUNT cell; the TOUCH column (Desktop only) shows a centred Lucide <code>fingerprint</code> icon and is <strong>not sortable</strong>.</p><h2 id="css-class-mapping" tabindex="-1">CSS Class Mapping <a class="header-anchor" href="#css-class-mapping" aria-label="Permalink to &quot;CSS Class Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma element</th><th>CSS class</th><th>Notes</th></tr></thead><tbody><tr><td>Outer container</td><td><code>.datatables</code></td><td>White bg, secondary border, <code>--ai-radius-md</code>, <code>overflow: hidden</code>. Replaces <code>.table-wrap</code> from the Table component.</td></tr><tr><td>Body scroll wrapper</td><td><code>.datatables__body</code></td><td>Inner div around the <code>&lt;table&gt;</code> only. <code>overflow-x: auto</code> lives here, so the toolbar above and pagination footer below stay fixed while the table content scrolls horizontally.</td></tr><tr><td>Mobile-scroll wrap</td><td><code>.datatables.datatables--mobile-scroll</code></td><td>Adds <code>max-width: 24rem</code>; the inner <code>.datatables__body</code> handles the scroll. Inner <code>.table</code> grows to <code>width: max-content</code> with <code>nowrap</code> cells</td></tr><tr><td>Toolbar</td><td><code>.datatables__toolbar</code></td><td>Flex row, white bg, bottom border. Padding <code>12/16</code> (vertical/horizontal)</td></tr><tr><td>Toolbar meta (left side)</td><td><code>.datatables__meta</code></td><td>Inline flex with text + <code>.datatables__select</code> for the row-count picker</td></tr><tr><td>Page-size select</td><td><code>.datatables__select</code></td><td>Button styled as a small select (40px tall on every Type since 2026-09-23, <code>--ai-radius-md</code>, chevron-down). Native <code>&lt;select&gt;</code> doesn&#39;t capture cleanly in Figma so this is a button</td></tr><tr><td>Toolbar search field</td><td><code>.datatables__search</code></td><td>Wraps the existing Input component; constrains to ≤18rem on desktop, full-width on mobile</td></tr><tr><td>Toolbar actions (right side)</td><td><code>.datatables__actions</code></td><td>Flex row of action buttons (uses Button component)</td></tr><tr><td>Sortable column header</td><td><code>&lt;button class=&quot;datatables__sort&quot;&gt;</code></td><td>Slots inside <code>&lt;th&gt;</code>; <code>--active</code> modifier flips the chevron icon to dark</td></tr><tr><td>Footer (pagination)</td><td><code>.datatables__footer</code></td><td>Flex row, white bg, top border. Padding <code>8-9/16</code></td></tr><tr><td>Pagination button group</td><td><code>.datatables__pagination</code></td><td>Connected segmented buttons inside a single radius-md outline</td></tr><tr><td>Pagination button</td><td><code>.datatables__page-btn</code></td><td>40×40 cells. <code>--active</code> modifier paints <code>--ai-datatable-table-footer-bg</code> background with bold text</td></tr><tr><td>Kebab toggle (Trigger only)</td><td><code>&lt;label class=&quot;datatables__kebab&quot;&gt;</code></td><td>Wraps a hidden checkbox + <code>more-vertical</code> icon</td></tr><tr><td>Kebab cell</td><td><code>.datatables__kebab-cell</code></td><td>Last <code>&lt;th&gt;</code>/<code>&lt;td&gt;</code> column, fixed 48px wide</td></tr><tr><td>Visible row</td><td><code>&lt;tr class=&quot;datatables__row&quot;&gt;</code></td><td>Pairs with the next sibling row</td></tr><tr><td>Detail row</td><td><code>&lt;tr class=&quot;datatables__row-detail&quot;&gt;</code></td><td>Hidden by default; revealed when the prev row&#39;s kebab input is <code>:checked</code></td></tr><tr><td>Detail definition list</td><td><code>&lt;dl class=&quot;datatables__detail-list&quot;&gt;</code></td><td>2-column grid of <code>&lt;dt&gt;</code> (uppercase label) / <code>&lt;dd&gt;</code> (value) pairs</td></tr><tr><td>User cell (Whos Online USER column)</td><td><code>&lt;div class=&quot;datatables__user-cell&quot;&gt;</code></td><td>Avatar + 2-line name/role stack</td></tr><tr><td>User text wrap</td><td><code>&lt;div class=&quot;datatables__user-text&quot;&gt;</code></td><td>Inside <code>.datatables__user-cell</code> — column of name + role</td></tr><tr><td>User name</td><td><code>&lt;span class=&quot;datatables__user-name&quot;&gt;</code></td><td>Title bold fixed-xs text-primary</td></tr><tr><td>User role / subtitle</td><td><code>&lt;span class=&quot;datatables__user-role&quot;&gt;</code></td><td>Body medium fixed-xs text-contrast</td></tr><tr><td>Centred icon cell (Whos Online TOUCH)</td><td><code>&lt;span class=&quot;datatables__icon-cell&quot;&gt;</code></td><td>Inline-flex; uses <code>--ai-icon-secondary</code></td></tr></tbody></table><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p>Datatables <strong>wraps the Table component</strong> — the inner <code>&lt;table class=&quot;table&quot;&gt;…&lt;/table&gt;</code> uses the production Table CSS for cell padding, header bg, dividers, etc. Datatables only adds the surrounding chrome:</p><ul><li><code>Button</code> (<code>src/components/Button/</code>) — toolbar actions, Delete-style buttons, and Whos Online row CTAs</li><li><code>Input</code> (<code>src/components/Input/</code>) — search field</li><li><code>Table</code> (<code>src/components/Table/</code>) — base table presentation</li><li><code>Avatar</code> (<code>src/components/Avatar/</code>) — Whos Online USER cell avatar (size 2)</li><li><code>Portraits</code> (<code>src/components/Portraits/</code>) — <code>&lt;img class=&quot;portrait&quot;&gt;</code> inside the Avatar</li><li>Lucide icon <code>fingerprint</code> — Whos Online TOUCH column (Desktop only)</li></ul><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><p>The Datatables chrome moved to a dedicated <code>--ai-datatable-*</code> token namespace (<code>components/global/datatable</code> in the Figma Semantic mode files) on 2026-05-07. The base Table component (<code>.table</code>) still uses generic semantic tokens; Datatables overrides the column-header bg and cell borders inside <code>.datatables .table</code> to switch to the namespaced tokens.</p><table tabindex="0"><thead><tr><th>Figma value</th><th>CSS variable</th><th>Role</th></tr></thead><tbody><tr><td><code>components/global/datatable/table-bg</code></td><td><code>--ai-datatable-table-bg</code></td><td>Outer container bg, page-size select bg, pagination wrap bg</td></tr><tr><td><code>components/global/datatable/table-header-bg</code></td><td><code>--ai-datatable-table-header-bg</code></td><td>Toolbar bg (above the table)</td></tr><tr><td><code>components/global/datatable/table-subheader-bg</code></td><td><code>--ai-datatable-table-subheader-bg</code></td><td>Column-header row bg (inside <code>.datatables .table thead th</code>)</td></tr><tr><td><code>components/global/datatable/table-footer-bg</code></td><td><code>--ai-datatable-table-footer-bg</code></td><td>Pagination footer bg, active page-btn bg, page-btn hover bg</td></tr><tr><td><code>components/global/datatable/table-expanded-bg</code></td><td><code>--ai-datatable-table-expanded-bg</code></td><td>Expanded row bg + detail-row bg + kebab hover bg</td></tr><tr><td><code>components/global/datatable/table-border</code></td><td><code>--ai-datatable-table-border</code></td><td>All chrome borders: container, toolbar, footer, pagination dividers, cell borders</td></tr><tr><td><code>text/primary</code></td><td><code>--ai-text-primary</code></td><td>Body text, page-btn label, sort-active icon</td></tr><tr><td><code>text/secondary</code></td><td><code>--ai-text-secondary</code></td><td>(inherited via Table) Header text</td></tr><tr><td><code>text/contrast</code></td><td><code>--ai-text-contrast</code></td><td>Toolbar meta text, footer text, detail-list <code>&lt;dt&gt;</code></td></tr><tr><td><code>icon/contrast</code></td><td><code>--ai-icon-contrast</code></td><td>Sort-icon (inactive), kebab icon, select chevron</td></tr><tr><td><code>radius/md</code> (8px)</td><td><code>--ai-radius-md</code></td><td>Container, select, kebab, page-btn group</td></tr><tr><td><code>spacing/2</code> (6px)</td><td><code>--ai-spacing-2</code></td><td>Meta gap, kebab→label gap</td></tr><tr><td><code>spacing/3</code> (8px)</td><td><code>--ai-spacing-3</code></td><td>Action gap, footer padding-y, select padding-x</td></tr><tr><td><code>spacing/4</code> (12px)</td><td><code>--ai-spacing-4</code></td><td>Toolbar gap, padding-y</td></tr><tr><td><code>spacing/5</code> (16px)</td><td><code>--ai-spacing-5</code></td><td>Toolbar/footer padding-x, detail-list column gap</td></tr><tr><td><code>spacing/7</code> (32px)</td><td><code>--ai-spacing-7</code></td><td>Select height</td></tr><tr><td><code>spacing/8</code> (40px)</td><td><code>--ai-spacing-8</code></td><td>Page-btn cell size</td></tr><tr><td><code>spacing/9</code> (48px)</td><td><code>--ai-spacing-9</code></td><td>Kebab cell width</td></tr><tr><td><code>font/title</code></td><td><code>--ai-font-title</code></td><td>All Datatables-specific text</td></tr><tr><td><code>font/fixed-xs</code> (14px)</td><td><code>--ai-font-fixed-xs</code></td><td>Footer text, meta text, page-btn label</td></tr><tr><td><code>font/fixed-xxs</code> (12px)</td><td><code>--ai-font-fixed-xxs</code></td><td>Detail <code>&lt;dt&gt;</code> (uppercase labels)</td></tr><tr><td><code>font/medium</code></td><td><code>--ai-font-medium</code></td><td>Page-size select label</td></tr><tr><td><code>font/bold</code></td><td><code>--ai-font-bold</code></td><td>Active page-btn, footer <code>&lt;strong&gt;</code></td></tr><tr><td><code>tracking/7</code> (0.05em)</td><td><code>--ai-tracking-7</code></td><td>Detail <code>&lt;dt&gt;</code> letter-spacing</td></tr></tbody></table><h2 id="token-gaps" tabindex="-1">Token Gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token Gaps&quot;">​</a></h2><p>None — every value maps to an existing <code>--ai-*</code> token.</p><h2 id="notes-inconsistencies" tabindex="-1">Notes / Inconsistencies <a class="header-anchor" href="#notes-inconsistencies" aria-label="Permalink to &quot;Notes / Inconsistencies&quot;">​</a></h2><ul><li><strong>Compact padding below 768px container width.</strong> <code>.datatables</code> is a <code>container-type: inline-size</code> context. In <code>@container (max-width: 767px)</code>, every element that uses spacing-5/spacing-4 padding at desktop (<code>.datatables__toolbar</code>, <code>.datatables__footer</code>, <code>.datatables__detail-list</code>, and the <code>.table</code> header/body cells) drops to a uniform <code>--ai-spacing-3</code> (8px) on both axes. The cell rules are scoped under <code>.datatables</code> so the base Table component used elsewhere is unaffected.</li><li><strong>Toolbar search is full-width below 768px.</strong> At desktop <code>.datatables__search</code> is <code>align-items: flex-end</code> (content-width, right-aligned) and the Input <code>--sm</code> wrap caps at <code>--ai-size-3</code> (192px). On a narrow toolbar that fixed width overflowed, so <code>@container (max-width: 767px)</code> switches the search to <code>align-items: stretch</code> and lifts the wrap&#39;s <code>max-width</code> to <code>none</code> — the field then fills the toolbar&#39;s remaining space and shrinks with it.</li><li><strong><code>.datatables__col--tight</code> column modifier.</strong> Add to a column&#39;s header <code>&lt;th&gt;</code> and every body <code>&lt;td&gt;</code> in that column to drop its right padding below 768px, collapsing the column toward its content so the freed width goes to its neighbour. Used on the <strong>Login</strong> column of the Whos Online · Trigger variant (so the wider User column gets the space). Rule lives in the <code>@container (max-width: 767px)</code> block with specificity raised above the cell-padding compaction.</li><li><strong>Header text colour discrepancy across variants.</strong> Figma binds the header <code>&lt;th&gt;</code> text to <code>--ai-text-primary</code> in some variants (Pagination Desktop) and <code>--ai-text-secondary</code> in others (Search Mobile, sometimes a single column within Pagination Mobile). The component normalises to <code>--ai-text-secondary</code> everywhere — inheriting the existing Table component&#39;s choice. Worth flagging to the designer.</li><li><strong>Layout via absolute positioning in Figma.</strong> Figma renders cells with absolute positioning + hardcoded pixel widths (e.g. <code>w-[356.469px]</code>). The production CSS uses native <code>&lt;table&gt;</code> with <code>border-collapse: collapse</code> and lets the browser distribute column widths — semantic, accessible, and resilient to content variation.</li><li><strong>Mobile scroll-indicator pill.</strong> The Mobile/Scroll variants in Figma include a small <code>bg-[var(--ai-surface-secondary)] h-[10px] rounded-full w-[180px]</code> pill at the bottom — a visual stand-in for the scrollbar. The production component uses the browser&#39;s native scrollbar.</li><li><strong>Pagination Mobile Trigger meta is just text</strong> (&quot;10 of 1,289&quot;) — no row-count select. Smaller toolbar to save space when the row layout already collapses to kebab.</li><li><strong>Search Desktop uses a primary Export button</strong> (with <code>download</code> icon); the Pagination variants use tertiary buttons throughout. The component HTML demos reflect both patterns.</li></ul><h2 id="interactivity" tabindex="-1">Interactivity <a class="header-anchor" href="#interactivity" aria-label="Permalink to &quot;Interactivity&quot;">​</a></h2><ul><li><strong>Kebab row expand</strong>: pure CSS via <code>:has(.datatables__kebab__input:checked) + .datatables__row-detail</code>. No JS; no popover dismiss; multiple rows can be open simultaneously. Each kebab is independent.</li><li><strong>Sort buttons, pagination, page-size select</strong>: visual only — actual sorting/pagination/page-size behaviour is the consumer&#39;s responsibility.</li></ul><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><code>Table</code> (<code>src/components/Table/</code>) — inner <code>&lt;table class=&quot;table&quot;&gt;</code> styling</li><li><code>Button</code> (<code>src/components/Button/</code>) — toolbar actions + Whos Online row CTAs</li><li><code>Input</code> (<code>src/components/Input/</code>) — Search variant&#39;s search field</li><li><code>Avatar</code> + <code>Portraits</code> (<code>src/components/Avatar/</code>, <code>src/components/Portraits/</code>) — Whos Online USER cell (size-2 avatar with portrait image)</li><li>Lucide icons — <code>chevron-down</code>, <code>chevron-left</code>, <code>chevron-right</code>, <code>chevrons-up-down</code>, <code>arrow-up-narrow-wide</code>, <code>more-vertical</code>, <code>filter</code>, <code>download</code>, <code>search</code>, <code>eye</code>, <code>fingerprint</code></li></ul><h2 id="row-controls-the-kebab-gained-a-hover-border" tabindex="-1">Row controls: the kebab gained a hover border <a class="header-anchor" href="#row-controls-the-kebab-gained-a-hover-border" aria-label="Permalink to &quot;Row controls: the kebab gained a hover border&quot;">​</a></h2><p>2026-09-18, designer. The kebab&#39;s hover was a background tint; it now also draws <code>1px solid var(--ai-border-secondary)</code> — the same line the table draws between its rows. The border is reserved as transparent at rest so the 32px box does not change size when the pointer arrives.</p><p>This came from the Orders listing, where a borderless edit pencil was added beside the kebab and the two have to read as one set of row controls. The rule lives here rather than in the template because the pair belongs to the component: any change to one belongs on both.</p><h2 id="pagination-collapses-to-a-position-readout-at-narrow-widths" tabindex="-1">Pagination collapses to a position readout at narrow widths <a class="header-anchor" href="#pagination-collapses-to-a-position-readout-at-narrow-widths" aria-label="Permalink to &quot;Pagination collapses to a position readout at narrow widths&quot;">​</a></h2><p>2026-09-21, designer. Seven page buttons plus two arrows cannot fit beside a count on a phone: measured at 390px the pager ran off the right edge from page 6 onward, and &quot;Showing 1–20 of 140 results&quot; wrapped to two lines.</p><p>Below a 767px CONTAINER the numbered buttons are replaced by &quot;Page 3 of 7&quot; and the count drops its two framing words, leaving &quot;1–20 of 140&quot;. Both fit on one row afterwards — 251px of content in 374px — so the footer is not stacked; stacking is the fallback for when compressing is not enough, and it costs a row of height on the screen with the least of it.</p><p>This is the common pattern rather than a house one: Material&#39;s table pagination, Polaris and Carbon all drop numbered buttons for arrows plus a position readout at small sizes, and GOV.UK keeps only a heavily windowed set. Jumping to page 5 is a desktop gesture; on a phone it is next and previous that get used.</p><p><strong>Both forms are always rendered and CSS picks one</strong> — JS cannot read a container query, and the swap is a container-width question (CLAUDE.md §4a).</p><p>One thing the swap broke and had to be fixed with it: the group&#39;s dividers were <code>.datatables__page-btn + .datatables__page-btn</code>, and <code>+</code> still counts a <code>display: none</code> sibling — so whichever of the two forms was hidden, the Next arrow lost its divider whenever the hidden member sat in front of it. The dividers now sit between the GROUP&#39;s children (arrow, number set, readout, arrow), with a second rule between the numbers inside their own wrapper.</p><h2 id="the-kebab-gets-the-row-s-gutter" tabindex="-1">The kebab gets the row&#39;s gutter <a class="header-anchor" href="#the-kebab-gets-the-row-s-gutter" aria-label="Permalink to &quot;The kebab gets the row&#39;s gutter&quot;">​</a></h2><p>2026-09-21, designer. Figma&#39;s mobile frame puts the kebab cell flush to the row edge (<code>--ai-spacing-0</code> both sides). Overruled: flush reads as the control falling off the table, and since the kebab is the last thing in the row, the row&#39;s right-hand gutter has to come from that cell or it does not exist.</p><ul><li><strong>Right: <code>--ai-spacing-4</code> (12px)</strong> at narrow container widths — the same value the other cells use on their leading edge, so the gutter matches the one down the left of the table.</li><li><strong>Left stays tight (4px)</strong> where the pencil is beside it: the two are one pair, and that was the point of tightening it.</li><li><strong>Left becomes 12px below 1024</strong>, where the device rule hides the pencil. With nothing to pair with, 4px is a collision with whatever data column happens to end the row rather than a pairing.</li></ul><p>That last rule sits AFTER the container block on purpose: the two selectors carry the same specificity, so source order decides, and this one has to win where they overlap — a narrow container on a phone.</p><p>An instruction that overrides the Figma frame, not a reading of it, so the file wants updating rather than this being &quot;corrected&quot; back to flush.</p><p>Tuned down twice on screen, and the final values are <strong>8px right at desktop</strong> (down from the 16 every other cell takes) and <strong>6px right when the container is narrow</strong>. The kebab is a 32px box with its own internal breathing room, so the cell&#39;s padding is the only thing between the icon and the table edge — at 16 it read as a margin rather than a gutter. Left stays 4px beside the pencil, 8px below 1024 where there is no pencil to pair with.</p><p>Measured: the kebab box sits 6-14px off the row edge depending on width, the variation being the fit giving that column its measured width rather than exactly the content&#39;s.</p><h2 id="and-the-chip-follows-its-column" tabindex="-1">…and the chip follows its column <a class="header-anchor" href="#and-the-chip-follows-its-column" aria-label="Permalink to &quot;…and the chip follows its column&quot;">​</a></h2><p>Same change, same cause as the title: under fixed layout the account/section chip was CROPPED when the fit handed its column less than the chip&#39;s 160px cap. <code>max-inline-size: min(var(--ai-size-2), 100%)</code> — the percentage resolves, because a fixed-layout cell has a definite width — so the chip ellipsises at the column instead of overflowing it. <code>sizeColumns</code> also stops taking a snug column below 128px when it is trimming to fit, which is the width at which a chip is still worth reading.</p><h2 id="the-active-sort-chevron-is-neutral-not-brand" tabindex="-1">The active sort chevron is neutral, not brand <a class="header-anchor" href="#the-active-sort-chevron-is-neutral-not-brand" aria-label="Permalink to &quot;The active sort chevron is neutral, not brand&quot;">​</a></h2><p>2026-09-21, designer: it was the one coloured thing in a row of grey chevrons and read as a link rather than as a state.</p><p>It does not need the colour. The control is a chevron PAIR at rest and a single direction chevron once a column is sorting, so the shape already carries the state — and <code>--ai-text-primary</code> matches the label sitting beside it, so the two now darken together.</p><p>Worth knowing how it got there: <strong>two rules 900 lines apart set the same property to different values</strong>, <code>--ai-text-primary</code> first and <code>--ai-icon-brand</code> second, and the later one quietly won. The duplicate is gone with the fix.</p><p>Measured, active / inactive / label: light <code>rgb(0,34,47)</code> / <code>rgb(153,170,177)</code> / <code>rgb(0,34,47)</code>; dark <code>rgb(241,245,249)</code> / <code>rgb(148,163,184)</code> / same; CC as light. Icon and label match in every mode, and the active one is plainly darker than the rest without being a different hue.</p><h2 id="the-container-clips-with-overflow-clip-not-hidden" tabindex="-1">The container clips with <code>overflow: clip</code>, not <code>hidden</code> <a class="header-anchor" href="#the-container-clips-with-overflow-clip-not-hidden" aria-label="Permalink to &quot;The container clips with `overflow: clip`, not `hidden`&quot;">​</a></h2><p>2026-09-23. Both clip the children to the rounded corners, but <code>hidden</code> also makes <code>.datatables</code> a scroll container, so any <code>position: sticky</code> descendant sticks to it — and it never scrolls. That blocked ListingScreen&#39;s selection bar from pinning under the CC header. <code>clip</code> paints the same and creates no scroll container. <code>overflow: hidden</code> stays as the line before it, as a fallback for browsers without <code>clip</code> (where a sticky child simply does not stick).</p>',53)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
